  font-weight: var(--typography-microcopy-xs-subtle-font-weight);
  line-height: var(--typography-microcopy-xs-subtle-line-height);
  letter-spacing: var(--typography-microcopy-xs-subtle-letter-spacing);
}
.typography-microcopy-xs-strong {
  font-family: var(--typography-microcopy-xs-strong-font-family);
  font-size: var(--typography-microcopy-xs-strong-font-size);
  font-weight: var(--typography-microcopy-xs-strong-font-weight);
  line-height: var(--typography-microcopy-xs-strong-line-height);
  letter-spacing: var(--typography-microcopy-xs-strong-letter-spacing);
}
.bcn-rp {
  align-items: center;
  gap: var(--spacing-100);
  display: inline-flex;
}
.bcn-rp__body {
  gap: var(--spacing-400);
  flex-direction: column;
  display: flex;
}
.bcn-rp__list {
  margin: 0 calc(-1 * var(--spacing-200));
  padding: 0;
  list-style: none;
}
.bcn-rp .bcn-rp__row {
  column-gap: var(--spacing-200);
  padding: var(--spacing-200);
  border-radius: var(--radius-md);
  color: var(--color-content-default);
  grid-template-columns: 1rem 3.75rem minmax(0, 1fr);
  align-items: baseline;
  row-gap: 2px;
  text-decoration: none;
  display: grid;
}
.bcn-rp .bcn-rp__row:hover {
  background: var(--color-background-elevation-sunken);
}
.bcn-rp .bcn-rp__row[aria-current] {
  background: var(--color-background-elevation-sunken);
  box-shadow: inset 0 0 0 1px var(--color-border-default);
}
.bcn-rp .bcn-rp__row:focus-visible {
  outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color);
  outline-offset: -2px;
}
.bcn-rp .bcn-rp__mark {
  justify-content: center;
  align-self: center;
  display: inline-flex;
}
.bcn-rp .bcn-rp__unread {
  background: var(--color-background-brand);
  border-radius: 50%;
  width: 0.5rem;
  height: 0.5rem;
}
.bcn-rp .bcn-rp__glyph {
  color: var(--color-content-secondary);
  display: inline-flex;
}
.bcn-rp .bcn-rp__glyph[data-state="done"] {
  color: var(--color-content-success, var(--color-content-default));
}
.bcn-rp .bcn-rp__no {
  font-size: var(--typography-label-sm-font-size);
  font-variant-numeric: tabular-nums;
  color: var(--color-content-secondary);
}
.bcn-rp .bcn-rp__name {
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-font-weight-medium, 500);
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
}
.bcn-rp .bcn-rp__row[aria-current] .bcn-rp__name {
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-rp .bcn-rp__meta {
  align-items: center;
  gap: var(--spacing-100) var(--spacing-300);
  font-size: var(--typography-label-sm-font-size);
  color: var(--color-content-secondary);
  flex-wrap: wrap;
  grid-column: 3;
  display: flex;
}
.bcn-rp .bcn-rp__status[data-state="open"] {
  color: var(--color-content-default);
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-rp .bcn-rp__topic {
  align-items: center;
  gap: var(--spacing-100);
  display: inline-flex;
}
.bcn-key-value__key .esa-icon {
  color: var(--color-content-default-tertiary);
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--xs {
  --_icon-size: var(--icon-size-xs, 14px);
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, 20px);
}
.esa-icon--lg {
  --_icon-size: var(--icon-size-lg, 24px);
}
.esa-icon--xl {
  --_icon-size: var(--icon-size-xl, 28px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}
.breadcrumbs__items .esa-icon {
